function Init-Dir([string]$Path) { if(-not [string]::IsNullOrWhiteSpace($Path) -and -not [IO.Directory]::Exists($Path)){[void][IO.Directory]::CreateDirectory($Path)} }
function Write-Text([string]$Name,[AllowEmptyString()][string]$Value) { $path=Join-Path $EvidenceRoot $Name;Init-Dir ([IO.Path]::GetDirectoryName($path));[IO.File]::WriteAllText($path,$Value,(New-Object Text.UTF8Encoding($false))) }
function Write-ExternalJson([string]$Path,$Value) { Init-Dir ([IO.Path]::GetDirectoryName($Path));[IO.File]::WriteAllText($Path,(($Value|ConvertTo-Json -Depth 30)+( [Environment]::NewLine)),(New-Object Text.UTF8Encoding($false))) }
function Write-Json([string]$Name,$Value) { if([IO.Path]::IsPathRooted($Name)){Write-ExternalJson $Name $Value}else{Write-Text $Name (($Value|ConvertTo-Json -Depth 30)+( [Environment]::NewLine))} }
function File-Sha([string]$Path) { return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToUpperInvariant() }
function Add-Gate([string]$Name,[string]$Result,[string]$Detail) {[void]$Gates.Add([pscustomobject]@{Gate=$Name;Status=$Result;Detail=$Detail})}
