function Add-Action([string]$Name,[string]$Result,[string]$Detail) {[void]$Actions.Add([pscustomobject]@{Action=$Name;Status=$Result;Detail=$Detail})}
function Invoke-Http([string]$Method,[string]$Uri,[hashtable]$Headers,$Body) { try{$params=@{UseBasicParsing=$true;Method=$Method;Uri=$Uri;Headers=$Headers;TimeoutSec=20};if($null-ne$Body){$params.ContentType='application/json';$params.Body=($Body|ConvertTo-Json -Compress)};$response=Invoke-WebRequest @params;return [pscustomobject]@{status=[int]$response.StatusCode;body=[string]$response.Content}}catch{$responseStatus=0;$responseBody='';if($null-ne$_.Exception.Response){$responseStatus=[int]$_.Exception.Response.StatusCode.value__;try{$responseBody=$_.ErrorDetails.Message}catch{}};return [pscustomobject]@{status=$responseStatus;body=$responseBody}} }
function Invoke-NativeCapture([string]$Executable,[string[]]$CommandArgs,[string]$WorkingDirectory) { try { $captured=& $Executable @CommandArgs 2>&1 | Out-String;$exitCode=$LASTEXITCODE;return [pscustomobject]@{exitCode=$exitCode;output=$captured} } catch { return [pscustomobject]@{exitCode=1;output=$_.Exception.Message} } }
