    if($Failures.Count -eq 0){$Status='PASS'};Write-Json '46_PRE_GREEN_HANDOFF.json' ([pscustomobject]@{preGreen=($Status -eq 'PASS');greenDeploymentAuthorization=$(if($Status -eq 'PASS'){'READY_FOR_SEPARATE_AUTHORITY'}else{'NO'});status=$Status});Write-Json '47_FINAL_STATUS.json' ([pscustomobject]@{status=$Status;primaryFailure=$PrimaryFailure;authority=$Authority});Write-Text '51_AUTHORITY_CLOSEOUT_TOKEN.txt' ('PRE_GREEN_GATE='+$(if($Status -eq 'PASS'){'PASS'}else{'BLOCKED'})+[Environment]::NewLine+'GREEN_DEPLOYMENT_AUTHORIZATION='+$(if($Status -eq 'PASS'){'READY_FOR_SEPARATE_AUTHORITY'}else{'NO'})+[Environment]::NewLine+'OVERALL_STATUS='+$Status+[Environment]::NewLine);Write-Text 'FINAL_STATUS.txt' ('OVERALL_STATUS='+$Status+[Environment]::NewLine+'PRIMARY_FAILURE='+$PrimaryFailure+[Environment]::NewLine);Write-Text 'FINAL_REPORT.md' ('# Phase 7 V1.0.1 Final Report'+[Environment]::NewLine+[Environment]::NewLine+'Status: '+$Status+[Environment]::NewLine+'Primary failure: '+$PrimaryFailure+[Environment]::NewLine);Write-Json 'summary.json' ([pscustomobject]@{status=$Status;primaryFailure=$PrimaryFailure;gateCount=$Gates.Count;failureCount=$Failures.Count});Write-Json 'progress.json' ([pscustomobject]@{stage='FINALIZED';status=$Status});Write-Text 'progress.csv' ('Stage,Status'+[Environment]::NewLine+'FINALIZED,'+$Status+[Environment]::NewLine);Write-Text 'checkpoint.json' '{"stage":"FINALIZED"}';Write-Text 'validations.csv' 'Validation,Status';Write-Text 'actions.csv' 'Action,Status,Detail';Write-Text 'failures.csv' 'FailureClass,Status,Detail';Write-Text 'warnings.csv' 'Warning,Status';Write-Text 'ERROR_LOG.txt' (($Failures|ConvertTo-Json -Depth 10)+[Environment]::NewLine);Write-Text 'EXECUTION_LOG.txt' ('AUTHORITY='+$Authority+[Environment]::NewLine+'FINAL_STATUS='+$Status+[Environment]::NewLine)
    $manifest=@(Get-ChildItem -LiteralPath $EvidenceRoot -File|ForEach-Object{[pscustomobject]@{name=$_.Name;sha256=(File-Sha $_.FullName)}});Write-Json '48_EVIDENCE_MANIFEST.json' $manifest;Write-Text '49_EVIDENCE_SHA256.txt' ((@($manifest|ForEach-Object{$_.sha256+'  '+$_.name}) -join [Environment]::NewLine)+[Environment]::NewLine);Add-Type -AssemblyName System.IO.Compression.FileSystem;if([IO.File]::Exists($EvidenceZip)){Remove-Item -LiteralPath $EvidenceZip -Force};[IO.Compression.ZipFile]::CreateFromDirectory($EvidenceRoot,$EvidenceZip);$archive=[IO.Compression.ZipFile]::OpenRead($EvidenceZip);$entryCount=$archive.Entries.Count;$archive.Dispose();$zipHash=File-Sha $EvidenceZip;Write-Json '50_ZIP_REOPEN_MODEL.json' ([pscustomobject]@{reopened=$true;entryCount=$entryCount;sha256=$zipHash});Write-ExternalJson $SidecarPath ([pscustomobject]@{status='PASS';zip=$EvidenceZip;sha256=$zipHash;entryCount=$entryCount;reopened=$true});Write-Output 'APEX_PS1_SKILL_UPDATE_NOT_REQUIRED';Write-Output ('EVIDENCE_ROOT='+$EvidenceRoot);Write-Output ('EVIDENCE_ZIP='+$EvidenceZip);Write-Output ('FINAL_SIDECAR='+$SidecarPath);Write-Output ('PRE_GREEN_GATE='+$(if($Status -eq 'PASS'){'PASS'}else{'BLOCKED'}));Write-Output ('OVERALL_STATUS='+$Status);if($Status -ne 'PASS'){exit 1}else{exit 0}
} catch { $failureMessage=$_.Exception.Message;Write-Text 'ERROR_LOG.txt' $failureMessage;Add-Failure 'APEX_PHASE7_V101_CONTROLLER_UNHANDLED_FAILURE' $failureMessage;Write-Text 'FINAL_STATUS.txt' ('OVERALL_STATUS=BLOCKED'+[Environment]::NewLine+'PRIMARY_FAILURE='+$PrimaryFailure+[Environment]::NewLine);exit 1 }
